from __future__ import annotations

from pathlib import Path

from fastapi import APIRouter
from fastapi.responses import HTMLResponse

router = APIRouter(tags=["dashboard"])

ATLAS_LOGO_B64 = Path(__file__).with_name("atlas_logo.b64").read_text(encoding="utf-8-sig").strip()


def dashboard_view() -> HTMLResponse:
    return HTMLResponse(DASHBOARD_HTML.replace(
        "</body>", '<script src="/ui/preferences.js"></script></body>'))


DASHBOARD_HTML = r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>ATLAS Live Trading Intelligence</title>
<style>
:root{color-scheme:dark;--card:#0d131d;--line:#3d3420;--gold:#ffd54a;--text:#ffd75c;--muted:#d7b75b;--orange:#ff8a24;--green:#62e6a2;--red:#ff7282}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 15% 0,#2b2413 0,#08090c 42%);color:var(--text);font:15px 'Rajdhani','Segoe UI',Tahoma,Arial,sans-serif;letter-spacing:.02em}main{max-width:1500px;margin:auto;padding:22px}.top{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:18px}.brand{display:flex;gap:12px;align-items:center}.logo{width:46px;height:46px;border:1px solid var(--gold);border-radius:15px;display:grid;place-items:center;font-weight:900;color:var(--gold);box-shadow:0 0 24px #ffd54a22}.logo-img{width:64px;height:64px;object-fit:cover;border:1px solid var(--gold);border-radius:18px;box-shadow:0 0 28px #ff8a2433}.title{font-size:24px;font-weight:900;letter-spacing:.08em;color:var(--gold)}.sub,.mini{font-size:11px;color:var(--muted)}.actions{display:flex;gap:8px;align-items:center}.btn,.trade-btn{border:0;color:#0b0c0e;background:var(--gold);padding:10px 13px;border-radius:11px;font:800 14px 'Rajdhani','Segoe UI',sans-serif;cursor:pointer;text-decoration:none}.trade-btn.sell{background:#ff9b68}.badge{border:1px solid var(--gold);padding:9px 11px;border-radius:999px;font-weight:800;color:var(--gold)}.grid{display:grid;gap:12px}.stats{grid-template-columns:repeat(6,1fr)}.split{grid-template-columns:1.65fr 1fr}.trade-grid{grid-template-columns:1.2fr .8fr}.card{background:linear-gradient(180deg,#15140f,#0b0e13);border:1px solid var(--line);border-radius:17px;padding:16px;box-shadow:0 16px 45px #0006}.label{color:var(--gold);font-size:11px;text-transform:uppercase;letter-spacing:.13em;font-weight:800}.big{font-size:24px;font-weight:900;margin-top:6px;color:var(--gold)}.green{color:var(--green)!important}.red{color:var(--red)!important}.yellow{color:var(--gold)!important}.row{display:grid;grid-template-columns:1.2fr .8fr .7fr .7fr .65fr;gap:8px;padding:10px 0;border-bottom:1px solid var(--line);align-items:center}.market{display:grid;grid-template-columns:1.1fr .8fr .6fr .45fr;gap:8px;padding:9px 0;border-bottom:1px solid var(--line);align-items:center}.pos{display:grid;grid-template-columns:1fr .65fr .75fr .7fr;gap:8px;padding:9px 0;border-bottom:1px solid var(--line)}.tag{display:inline-block;border:1px solid var(--line);border-radius:999px;padding:4px 8px;font-size:10px;color:var(--gold)}.empty{color:var(--muted);padding:12px 0}.notice{border-left:3px solid var(--gold);padding:10px 12px;background:#ffd54a0b;border-radius:8px;color:var(--muted);margin-top:12px}.story{display:block;padding:10px 0;border-bottom:1px solid var(--line);color:var(--text);text-decoration:none}.story:hover{color:var(--gold)}select{width:100%;background:#0d1118;color:var(--gold);border:1px solid var(--line);border-radius:10px;padding:10px;font:inherit}.quote{display:flex;align-items:baseline;gap:10px;margin:10px 0}.quote .price{font-size:34px;font-weight:900;color:var(--gold)}.chart{width:100%;height:170px;background:#090b10;border:1px solid var(--line);border-radius:12px;margin:10px 0}.trade-actions{display:flex;gap:10px;margin-top:12px}.demo-position{margin-top:12px;padding:12px;border:1px dashed var(--line);border-radius:12px}.demo-only{font-size:11px;color:var(--muted);margin-top:8px}@media(max-width:1100px){.stats{grid-template-columns:repeat(3,1fr)}.split,.trade-grid{grid-template-columns:1fr}}@media(max-width:720px){main{padding:12px}.stats{grid-template-columns:1fr 1fr}.top{align-items:flex-start;flex-direction:column}.row,.pos,.market{grid-template-columns:1fr 1fr}.trade-actions{flex-direction:column}}
</style></head><body><main>
<div class="top"><div class="brand"><img id="atlasLogo" class="logo-img" src="data:image/webp;base64,__ATLAS_LOGO_B64__" alt="ATLAS"><div><div class="title">ATLAS THE ULTIMATE</div><div class="sub">Live demo telemetry · Demo market viewer · No broker order submission</div></div></div><div class="actions"><a class="btn" href="/subscribe">Subscriptions</a><div class="badge" id="status">CONNECTING</div></div></div>

<section class="card" id="atlasAiChart" style="margin-top:12px"><div class="label">AI Chart</div><div class="grid" style="grid-template-columns:minmax(150px,.35fr) 1fr;align-items:end"><label class="mini" for="aiTimeframe">Timeframe<select id="aiTimeframe"><option value="12">Short</option><option value="24">Medium</option><option value="40" selected>Extended</option></select></label><div class="grid" style="grid-template-columns:repeat(4,1fr)"><div><div class="mini">AI Trend</div><b id="aiTrend">NEUTRAL</b></div><div><div class="mini">AI Momentum</div><b id="aiMomentum">?</b></div><div><div class="mini">AI Signal</div><b id="aiSignal">OBSERVE</b></div><div><div class="mini">AI Confidence</div><b id="aiConfidence">?</b></div></div></div><svg class="chart" viewBox="0 0 600 170" preserveAspectRatio="none"><polyline id="aiPriceLine" fill="none" stroke="#ff8a24" stroke-width="3" points=""></polyline></svg><div class="mini">AI telemetry is contextual only and does not place or recommend trades.</div></section>
<div class="grid stats"><div class="card"><div class="label">Account Type</div><div class="big" id="accountType">—</div></div><div class="card"><div class="label">Equity</div><div class="big" id="equity">—</div></div><div class="card"><div class="label">Balance</div><div class="big" id="balance">—</div></div><div class="card"><div class="label">Floating P/L</div><div class="big" id="floating">—</div></div><div class="card"><div class="label">Open Positions</div><div class="big" id="openPositions">—</div></div><div class="card"><div class="label">Execution Gate</div><div class="big yellow" id="execution">—</div></div></div>
<div class="grid trade-grid" style="margin-top:12px"><section class="card"><div class="label">Live Asset Viewer</div><label class="mini" for="assetSelect">Asset</label><select id="assetSelect"></select><div class="quote"><span class="price" id="assetPrice">—</span><span id="assetMove" class="mini">—</span></div><svg id="priceChart" class="chart" viewBox="0 0 600 170" preserveAspectRatio="none"><polyline id="priceLine" fill="none" stroke="#ffd54a" stroke-width="3" points=""></polyline></svg><div class="mini">Live prices update from the connected FxPro MT5 demo feed.</div></section><section class="card"><div class="label">Live Demo Trading</div><div class="mini">Current Price</div><div class="big" id="tradePrice">—</div><div class="trade-actions"><button class="trade-btn" data-demo-action="BUY">Buy Demo</button><button class="trade-btn sell" data-demo-action="SELL">Sell Demo</button></div><div id="demoPosition" class="demo-position"><div class="empty">No demo position open.</div></div><button id="closeDemo" class="trade-btn" style="display:none;margin-top:10px">Close Demo Position</button><div class="demo-only">Demo only. These controls never submit an order to MT5 or FxPro.</div></section></div>
<div class="grid split" style="margin-top:12px"><section class="card"><div class="label">ATLAS Opportunity Matrix</div><div id="signals"></div></section><section class="card"><div class="label">Verified Account</div><div id="account"></div><div class="label" style="margin-top:18px">Open Positions</div><div id="positions"></div></section></div>
<div class="grid split" style="margin-top:12px"><section class="card"><div class="label">Wall Street Board · Context only</div><div id="marketBoard"></div></section><section class="card"><div class="label">Financial News · Context only</div><div id="headlines"></div></section></div>
<div class="notice" id="disclaimer">Read-only telemetry. Trading involves risk.</div></main>
<script>
const priceHistory={},assetMap={};let currentAsset='',lastPrice=null,demoPosition=null;
function el(id){return document.getElementById(id)}function esc(value){return String(value==null?'':value).replace(/[&<>'"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]})}function money(value,currency){if(value==null)return 'PRIVATE';return Number(value).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2})+(currency?' '+currency:'')}function tone(value){return Number(value)>=0?'green':'red'}
function currentLanguage(){try{return localStorage.getItem('atlas-language')==='ar'?'ar':'en'}catch(e){return 'en'}}
window.addEventListener('storage',function(e){if(e.key==='atlas-language')refreshBriefing()});document.addEventListener('change',function(e){if(e.target&&e.target.id==='atlas-lang')setTimeout(refreshBriefing,0)});
function signalRow(x){return '<div class="row"><div><b>'+esc(x.canonical_symbol||x.symbol)+'</b><div class="mini"><span>'+esc(x.asset_class)+'</span> · <span>'+esc(x.symbol)+'</span></div></div><div><span class="tag">'+esc(x.decision.bias)+'</span><div class="mini">'+esc(x.decision.decision)+'</div></div><div><b>'+Number(x.decision.score||0).toFixed(1)+'</b><div class="mini">score</div></div><div><b>'+Number(x.quality.execution_confidence||0).toFixed(1)+'%</b><div class="mini">confidence</div></div><div><b>'+Number(x.opportunity_score||0).toFixed(0)+'</b><div class="mini">opportunity</div></div></div>'}
function updateAssetOptions(symbols){const select=el('assetSelect'),wanted=currentAsset||select.value;symbols.forEach(x=>assetMap[x.canonical_symbol||x.symbol]=x);const names=symbols.map(x=>x.canonical_symbol||x.symbol);if(select.options.length!==names.length||names.some((n,i)=>!select.options[i]||select.options[i].value!==n)){select.innerHTML=names.map(n=>'<option value="'+esc(n)+'">'+esc(n)+'</option>').join('')}currentAsset=names.includes(wanted)?wanted:(names[0]||'');select.value=currentAsset}
function drawChart(name,price){if(!name||!Number.isFinite(price))return;const history=priceHistory[name]||(priceHistory[name]=[]);if(!history.length||history[history.length-1]!==price)history.push(price);if(history.length>40)history.shift();if(history.length<2){el('priceLine').setAttribute('points','0,85 600,85');return}const min=Math.min(...history),max=Math.max(...history),span=(max-min)||1;const pts=history.map((p,i)=>{const x=i*(600/(history.length-1)),y=155-((p-min)/span)*140;return x.toFixed(1)+','+y.toFixed(1)}).join(' ');el('priceLine').setAttribute('points',pts)}

function updateAiChart(){const history=(priceHistory[currentAsset]||[]).slice(-Number(el('aiTimeframe').value||40));if(history.length<2){el('aiPriceLine').setAttribute('points','0,85 600,85');el('aiTrend').textContent='NEUTRAL';el('aiMomentum').textContent='?';el('aiSignal').textContent='OBSERVE';el('aiConfidence').textContent='?';return}const min=Math.min(...history),max=Math.max(...history),span=(max-min)||1;const pts=history.map((p,i)=>{const x=i*(600/(history.length-1)),y=155-((p-min)/span)*140;return x.toFixed(1)+','+y.toFixed(1)}).join(' ');el('aiPriceLine').setAttribute('points',pts);const delta=history[history.length-1]-history[0],trend=delta>0?'BULLISH':delta<0?'BEARISH':'NEUTRAL';el('aiTrend').textContent=trend;el('aiMomentum').textContent=Math.abs(delta).toFixed(6);el('aiSignal').textContent='OBSERVE';el('aiConfidence').textContent=Math.min(100,Math.round((history.length/40)*100))+'%'}
function updateAssetViewer(){const item=assetMap[currentAsset];if(!item)return;const price=Number(item.price||0);const previous=lastPrice;lastPrice=price;el('assetPrice').textContent=price.toLocaleString(undefined,{maximumFractionDigits:6});el('tradePrice').textContent=el('assetPrice').textContent;const move=previous==null?0:price-previous;el('assetMove').textContent=move===0?'—':(move>0?'▲ ':'▼ ')+Math.abs(move).toFixed(6);el('assetMove').className='mini '+(move>=0?'green':'red');drawChart(currentAsset,price);updateAiChart();renderDemoPosition(price)}
function demoTrade(side){const item=assetMap[currentAsset];if(!item)return;demoPosition={side:side,symbol:currentAsset,entry:Number(item.price||0),openedAt:Date.now()};renderDemoPosition(demoPosition.entry)}
function renderDemoPosition(currentPrice){if(!demoPosition){el('demoPosition').innerHTML='<div class="empty">No demo position open.</div>';el('closeDemo').style.display='none';return}const entry=demoPosition.entry,current=Number(currentPrice||entry),direction=demoPosition.side==='BUY'?1:-1,pct=entry?direction*((current-entry)/entry)*100:0;el('demoPosition').innerHTML='<div><b><span>'+esc(demoPosition.side)+'</span> · <span>'+esc(demoPosition.symbol)+'</span></b></div><div class="mini">Entry</div><div>'+entry.toLocaleString(undefined,{maximumFractionDigits:6})+'</div><div class="mini">Current Price</div><div>'+current.toLocaleString(undefined,{maximumFractionDigits:6})+'</div><div class="mini">Demo P/L</div><div class="'+tone(pct)+'"><b>'+pct.toFixed(3)+'%</b></div>';el('closeDemo').style.display='inline-block'}
el('assetSelect').addEventListener('change',e=>{currentAsset=e.target.value;lastPrice=null;updateAssetViewer()});el('aiTimeframe').addEventListener('change',updateAiChart);document.querySelectorAll('[data-demo-action]').forEach(btn=>btn.addEventListener('click',()=>demoTrade(btn.dataset.demoAction)));el('closeDemo').addEventListener('click',()=>{demoPosition=null;renderDemoPosition(0)});
async function refresh(){try{const response=await fetch('/dashboard/atlas',{cache:'no-store'});if(!response.ok)throw Error('offline');const data=await response.json(),account=data.account||{},symbols=data.symbols||[];el('status').textContent=data.verified_live_account?'VERIFIED LIVE':'ONLINE';el('accountType').textContent=account.account_type||'—';el('accountType').className='big '+(account.account_type==='REAL'?'green':'yellow');el('equity').textContent=money(account.equity,account.currency);el('balance').textContent=money(account.balance,account.currency);el('floating').textContent=money(data.floating_position_pnl,account.currency);el('floating').className='big '+tone(data.floating_position_pnl);el('openPositions').textContent=data.open_positions||0;el('execution').textContent=data.services.execution_gate;el('account').innerHTML='<div class="pos"><span>'+esc(account.label)+'</span><b>'+esc(account.login)+'</b><span>'+esc(account.server)+'</span><b>1:'+esc(account.leverage||'—')+'</b></div>';el('signals').innerHTML=symbols.map(signalRow).join('')||'<div class="empty">No markets available.</div>';el('positions').innerHTML=(data.positions||[]).map(p=>'<div class="pos"><div><b>'+esc(p.symbol)+'</b><div class="mini">'+esc(p.direction)+'</div></div><div>'+p.volume+'</div><div>'+p.price_open+'</div><div class="'+tone(p.profit)+'"><b>'+Number(p.profit||0).toFixed(2)+'</b></div></div>').join('')||'<div class="empty">No open positions.</div>';el('disclaimer').textContent=data.disclaimer;updateAssetOptions(symbols);updateAssetViewer()}catch(error){el('status').textContent='OFFLINE'}}
async function refreshBriefing(){try{const language=currentLanguage(),response=await fetch('/dashboard/market-briefing?language='+encodeURIComponent(language),{cache:'no-store'}),data=await response.json();if(!response.ok)throw Error('unavailable');el('marketBoard').innerHTML=(data.market_board||[]).map(x=>'<div class="market"><div><b>'+esc(x.label)+'</b><div class="mini">'+esc(x.category)+'</div></div><b>'+(x.price==null?'—':Number(x.price).toLocaleString())+'</b><b class="'+tone(x.change_percent)+'">'+(x.change_percent==null?'—':Number(x.change_percent).toFixed(2)+'%')+'</b><span class="tag">'+esc(x.market_state)+'</span></div>').join('')||'<div class="empty">Market data temporarily unavailable.</div>';el('headlines').innerHTML=(data.headlines||[]).map(x=>'<a class="story" href="'+esc(x.url)+'" target="_blank" rel="noopener"><b>'+esc(x.title)+'</b><div class="mini">'+esc(x.source)+' · '+esc(x.published_at)+'</div></a>').join('')||'<div class="empty">Financial headlines temporarily unavailable.</div>'}catch(error){el('marketBoard').innerHTML='<div class="empty">Market board unavailable.</div>';el('headlines').innerHTML='<div class="empty">Headlines unavailable.</div>'}}
refresh();refreshBriefing();setInterval(refresh,5000);setInterval(refreshBriefing,60000);
</script></body></html>'''

DASHBOARD_HTML = DASHBOARD_HTML.replace("__ATLAS_LOGO_B64__", ATLAS_LOGO_B64)
